1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// ParseAuditInput decodes an audit submission JSON object into domain values.
111	// Invariant values must be JSON booleans; any other type is an error.
112	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
113		var in wireInput
114		if err := json.Unmarshal(data, &in); err != nil {
115			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
116		}
117		invariants := make(map[string]bool, len(in.Invariants))
118		for key, raw := range in.Invariants {
119			// Only JSON true/false is a conclusion. Unmarshalling directly into a
120			// bool would turn null into the zero value false, which would falsely
121			// record a defect; require the token to be a boolean instead.
122			var token any
123			if err := json.Unmarshal(raw, &token); err != nil {
124				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
125			}
126			holds, ok := token.(bool)
127			if !ok {
128				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
129			}
130			invariants[key] = holds
131		}
132		artifact := Artifact{
133			Name:     in.Artifact.Name,
134			ABI:      in.Artifact.ABI,
135			Bytecode: in.Artifact.Bytecode,
136			Source:   in.Artifact.Source,
137		}
138		rules := make([]Rule, 0, len(in.Rules))
139		for _, wr := range in.Rules {
140			rules = append(rules, Rule{
141				ID:          wr.ID,
142				Kind:        wr.Kind,
143				Severity:    wr.Severity,
144				Invariant:   wr.Invariant,
145				RequiresABI: wr.RequiresABI,
146				Version:     wr.Version,
147			})
148		}
149		checks := make([]CheckRecord, 0, len(in.Checks))
150		for _, wc := range in.Checks {
151			checks = append(checks, CheckRecord{
152				ArtifactHash: wc.ArtifactHash,
153				RuleID:       wc.RuleID,
154				Version:      wc.Version,
155				Status:       wc.Status,
156				Note:         wc.Note,
157			})
158		}
159		return artifact, rules, invariants, checks, nil
160	}
161	
162	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
163	// bytecode and source strings contribute; field boundaries are explicit
164	// (length-prefixed) so that different splits never collide. The source is
165	// hashed as a field value, never read from disk, and the name does not
166	// participate.
167	func ArtifactHash(a Artifact) string {
168		h := sha256.New()
169		h.Write([]byte("contractsentinel-artifact-v1\n"))
170		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
171			fmt.Fprintf(h, "%d\n", len(field))
172			h.Write([]byte(field))
173		}
174		sum := h.Sum(nil)
175		return hex.EncodeToString(sum)
176	}
177	
178	// validCheckStatus reports whether status is one of the four recorded check
179	// conclusions.
180	func validCheckStatus(status string) bool {
181		switch status {
182		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
183			return true
184		}
185		return false
186	}
187	
188	// BuildReport evaluates rules against the artifact and invariant values and
189	// imported check records and produces the report to persist. Insufficient
190	// inputs (missing ABI for a rule that requires it, missing bytecode for a
191	// symbolic rule) fail the whole submission and are never recorded as defects.
192	// Imported checks are validated as a whole: unknown rules, duplicate records,
193	// unknown statuses, missing notes, hash or version mismatches, and a rule
194	// receiving both a check record and an invariant boolean all reject the
195	// submission without producing a report.
196	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
197		if artifact.Name == "" {
198			return Report{}, errInvalid("artifact name is required")
199		}
200		hash := ArtifactHash(artifact)
201		seen := make(map[string]bool, len(rules))
202		ruleByID := make(map[string]Rule, len(rules))
203		for _, rule := range rules {
204			if rule.ID == "" {
205				return Report{}, errInvalid("rule id is required")
206			}
207			if rule.Version == "" {
208				return Report{}, errInvalid("rule " + rule.ID + " version is required")
209			}
210			if seen[rule.ID] {
211				return Report{}, errInvalid("duplicate rule id " + rule.ID)
212			}
213			seen[rule.ID] = true
214			ruleByID[rule.ID] = rule
215			if rule.RequiresABI && artifact.ABI == "" {
216				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
217			}
218			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
219				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
220			}
221		}
222		checkByRule := make(map[string]CheckRecord, len(checks))
223		for _, check := range checks {
224			if check.RuleID == "" {
225				return Report{}, errInvalid("check rule id is required")
226			}
227			rule, ok := ruleByID[check.RuleID]
228			if !ok {
229				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
230			}
231			if _, dup := checkByRule[check.RuleID]; dup {
232				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
233			}
234			if check.ArtifactHash != hash {
235				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
236			}
237			if check.Version != rule.Version {
238				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
239			}
240			if !validCheckStatus(check.Status) {
241				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
242			}
243			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
244				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
245			}
246			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
247				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
248			}
249			checkByRule[check.RuleID] = check
250		}
251		report := Report{
252			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
253			Rules:    []ReportRule{},
254			Findings: []ReportFinding{},
255		}
256		for _, rule := range rules {
257			status := StatusUnchecked
258			note := ""
259			if check, ok := checkByRule[rule.ID]; ok {
260				status = check.Status
261				note = check.Note
262			} else if holds, checked := invariants[rule.Invariant]; checked {
263				if holds {
264					status = StatusPass
265				} else {
266					status = StatusDefect
267				}
268			}
269			report.Rules = append(report.Rules, ReportRule{
270				ID:          rule.ID,
271				Kind:        rule.Kind,
272				Severity:    rule.Severity,
273				Invariant:   rule.Invariant,
274				RequiresABI: rule.RequiresABI,
275				Version:     rule.Version,
276				Status:      status,
277				Note:        note,
278			})
279			if status == StatusDefect {
280				evidence := note
281				if evidence == "" {
282					evidence = "invariant " + rule.Invariant + " does not hold"
283				}
284				report.Findings = append(report.Findings, ReportFinding{
285					ArtifactHash: hash,
286					RuleID:       rule.ID,
287					Version:      rule.Version,
288					Severity:     rule.Severity,
289					Invariant:    rule.Invariant,
290					Evidence:     evidence,
291				})
292			}
293		}
294		report.ReportID = ReportID(report)
295		return report, nil
296	}
297	
298	// canonicalRule is the order-independent view of a rule used for the id. The
299	// note is omitted when empty so reports built only from invariant booleans
300	// keep their original ids.
301	type canonicalRule struct {
302		ID          string `json:"id"`
303		Kind        string `json:"kind"`
304		Severity    string `json:"severity"`
305		Invariant   string `json:"invariant"`
306		RequiresABI bool   `json:"requiresABI"`
307		Version     string `json:"version"`
308		Status      string `json:"status"`
309		Note        string `json:"note,omitempty"`
310	}
311	
312	// canonicalFinding is the order-independent view of a finding used for the id.
313	type canonicalFinding struct {
314		ArtifactHash string `json:"artifactHash"`
315		RuleID       string `json:"ruleId"`
316		Version      string `json:"version"`
317		Severity     string `json:"severity"`
318		Invariant    string `json:"invariant"`
319		Evidence     string `json:"evidence"`
320	}
321	
322	// canonicalReport is the deterministic content a report id is computed from.
323	type canonicalReport struct {
324		ArtifactHash string             `json:"artifactHash"`
325		Name         string             `json:"name"`
326		Rules        []canonicalRule    `json:"rules"`
327		Findings     []canonicalFinding `json:"findings"`
328	}
329	
330	// canonicalize renders a report into its order-independent form.
331	func canonicalize(report Report) canonicalReport {
332		cr := canonicalReport{
333			ArtifactHash: report.Artifact.Hash,
334			Name:         report.Artifact.Name,
335		}
336		for _, rule := range report.Rules {
337			cr.Rules = append(cr.Rules, canonicalRule{
338				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
339				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
340				Version: rule.Version, Status: rule.Status, Note: rule.Note,
341			})
342		}
343		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
344		for _, finding := range report.Findings {
345			cr.Findings = append(cr.Findings, canonicalFinding{
346				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
347				Version: finding.Version, Severity: finding.Severity,
348				Invariant: finding.Invariant, Evidence: finding.Evidence,
349			})
350		}
351		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
352		return cr
353	}
354	
355	// ReportID returns the content-addressed identifier of a report. The id binds
356	// the artifact hash, name, complete rule definitions, the invariant value
357	// used by each rule (unchecked and explicit pass are distinct), and the
358	// findings. Rule order, invariant key order and unrelated invariant keys do
359	// not influence it.
360	func ReportID(r Report) string {
361		data, err := json.Marshal(canonicalize(r))
362		if err != nil {
363			panic(err) // canonical values are all strings and bools
364		}
365		sum := sha256.Sum256(data)
366		return hex.EncodeToString(sum[:])
367	}
368	
369	// validateReport checks every archive legality condition against r. It is the
370	// single definition of a legal report: the id and artifact hash are 64
371	// lowercase hex characters, the id matches the content, the artifact name is
372	// present, rule ids are present and unique with non-empty versions, statuses
373	// use the five recorded values, tool-missing and timeout notes are
374	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
375	// artifact hash, version, severity, invariant and evidence match the rule.
376	// The same conditions apply to submissions and to stored archives: a
377	// recomputed id never makes an invalid report legal. fail is errInvalid for
378	// submissions and errCorrupt for stored archives.
379	func validateReport(r Report, fail func(string) error) error {
380		if !validReportID(r.ReportID) {
381			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
382		}
383		if r.Artifact.Name == "" {
384			return fail("report " + r.ReportID + " artifact name is required")
385		}
386		if !validReportID(r.Artifact.Hash) {
387			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
388		}
389		if ReportID(r) != r.ReportID {
390			return fail("report content does not match id " + r.ReportID)
391		}
392		seenRule := make(map[string]bool, len(r.Rules))
393		defectByID := make(map[string]ReportRule)
394		for _, rule := range r.Rules {
395			if rule.ID == "" {
396				return fail("report " + r.ReportID + " has a rule with an empty id")
397			}
398			if seenRule[rule.ID] {
399				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
400			}
401			seenRule[rule.ID] = true
402			if rule.Version == "" {
403				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
404			}
405			switch rule.Status {
406			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
407			default:
408				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
409			}
410			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
411				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
412			}
413			if rule.Status == StatusDefect {
414				defectByID[rule.ID] = rule
415			}
416		}
417		seenFinding := make(map[string]bool, len(r.Findings))
418		for _, f := range r.Findings {
419			if f.RuleID == "" {
420				return fail("report " + r.ReportID + " has a finding with an empty rule id")
421			}
422			rule, ok := defectByID[f.RuleID]
423			if !ok {
424				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
425			}
426			if seenFinding[f.RuleID] {
427				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
428			}
429			seenFinding[f.RuleID] = true
430			if f.ArtifactHash != r.Artifact.Hash {
431				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
432			}
433			if f.Version != rule.Version {
434				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
435			}
436			if f.Severity != rule.Severity {
437				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
438			}
439			if f.Invariant != rule.Invariant {
440				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
441			}
442			wantEvidence := rule.Note
443			if wantEvidence == "" {
444				wantEvidence = "invariant " + rule.Invariant + " does not hold"
445			}
446			if f.Evidence != wantEvidence {
447				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
448			}
449		}
450		for id := range defectByID {
451			if !seenFinding[id] {
452				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
453			}
454		}
455		return nil
456	}
457	
458	// validStoredReport validates archive contents.
459	func validStoredReport(r Report) error {
460		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
461	}
462	
463	// validSubmittedReport validates a submission before any store operation.
464	func validSubmittedReport(r Report) error {
465		return validateReport(r, func(msg string) error { return errInvalid(msg) })
466	}
467	
468	// loadStoredReport parses archive bytes for id and fully validates them.
469	func loadStoredReport(data []byte, id string) (Report, error) {
470		var r Report
471		if err := json.Unmarshal(data, &r); err != nil {
472			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
473		}
474		if r.ReportID != id {
475			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
476		}
477		if err := validStoredReport(r); err != nil {
478			return Report{}, err
479		}
480		return r, nil
481	}
482	
483	// saveReportHook, when set, is invoked after the archive existence check and
484	// before the atomic publish. It lets tests simulate another process racing to
485	// claim the same report id.
486	var saveReportHook func(finalPath string)
487	
488	// SaveReport persists a report under the store directory. The store is safe
489	// for concurrent writers: identical reports share one file and all
490	// submissions succeed, different reports never overwrite each other, and
491	// readers only ever observe complete files. A submission is fully validated
492	// before any store operation, so an invalid report creates no store and no
493	// files. A pre-existing file with the same id must be a valid archive of the
494	// same report; a corrupted archive makes the submission fail while keeping the
495	// original file, even when the corruption appears only during the save. The
496	// first successfully archived bytes are never replaced by later submissions.
497	func SaveReport(dir string, r Report) error {
498		if err := validSubmittedReport(r); err != nil {
499			return err
500		}
501		if err := os.MkdirAll(dir, 0o755); err != nil {
502			return err
503		}
504		finalPath := filepath.Join(dir, r.ReportID+".json")
505		if existing, err := os.ReadFile(finalPath); err == nil {
506			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
507				return err
508			}
509			return nil
510		} else if !os.IsNotExist(err) {
511			return err
512		}
513		data, err := json.Marshal(r)
514		if err != nil {
515			return err
516		}
517		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
518		if err != nil {
519			return err
520		}
521		tmpPath := tmp.Name()
522		cleanup := func() { os.Remove(tmpPath) }
523		if _, err := tmp.Write(data); err != nil {
524			tmp.Close()
525			cleanup()
526			return err
527		}
528		if err := tmp.Sync(); err != nil {
529			tmp.Close()
530			cleanup()
531			return err
532		}
533		if err := tmp.Close(); err != nil {
534			cleanup()
535			return err
536		}
537		if saveReportHook != nil {
538			saveReportHook(finalPath)
539		}
540		if err := os.Link(tmpPath, finalPath); err != nil {
541			cleanup()
542			if os.IsExist(err) {
543				existing, readErr := os.ReadFile(finalPath)
544				if readErr != nil {
545					return readErr
546				}
547				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
548					return err
549				}
550				return nil
551			}
552			return err
553		}
554		cleanup()
555		return nil
556	}
557	
558	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
559	// hex characters; missing, corrupted or tampered archives produce a clear
560	// error. The store is only read, never created or modified.
561	func LoadReport(dir, id string) (Report, error) {
562		if !validReportID(id) {
563			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
564		}
565		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
566		if err != nil {
567			if os.IsNotExist(err) {
568				return Report{}, errNotFound("report " + id + " not found")
569			}
570			return Report{}, err
571		}
572		return loadStoredReport(data, id)
573	}
574	
575	type errNotFound string
576	
577	func (e errNotFound) Error() string { return string(e) }
578	
579	type errCorrupt string
580	
581	func (e errCorrupt) Error() string { return string(e) }
582

