115	// runCLIAudit 在真实进程上运行 audit，返回 stdout、stderr 与退出码。
116	func runCLIAudit(t *testing.T, bin, input, store string) (string, string, int) {
117		t.Helper()
118		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
119		var stdout, stderr bytes.Buffer
