161	// 错误记录不能被降级标成缺陷、超时或未检查后部分输出。
162	func assertNoPartialReport(t *testing.T, stdout string) {
163		t.Helper()
164		if stdout != "" {
165			t.Fatalf("rejected submission must print nothing to stdout, got:\n%s", stdout)
166		}
167	}
