	id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
		stored.Findings = nil
	})
	expectCorruptLoad(t, dir, id, "r-bad")
}

// --- 损坏归属：缺陷引用正确规则但绑定其他产物 ---

func TestLoadReportRejectsFindingWrongArtifactHash(t *testing.T) {
