1207			Findings: []ReportFinding{
1208				{ArtifactHash: ArtifactHash(sampleArtifact()), RuleID: "r1", Version: "9.9.9", Severity: "high", Invariant: "inv", Evidence: "counterexample"},
1209			},
1210		}
1211		report.ReportID = ReportID(report)
1212		data, _ := json.Marshal(report)
1213		if err := os.WriteFile(filepath.Join(dir, report.ReportID+".json"), data, 0o644); err != nil {
1214			t.Fatal(err)
1215		}
1216		_, err := LoadReport(dir, report.ReportID)
1217		var ec errCorrupt
1218		if !errors.As(err, &ec) {
1219			t.Fatalf("expected errCorrupt, got %T: %v", err, err)
1220		}
1221	}
1222	
1223	func TestSaveReportPermutationKeepsFirstBytes(t *testing.T) {
1224		dir := t.TempDir()
1225		rules := sampleRules()
1226		r1, err := BuildReport(sampleArtifact(), rules, sampleInvariants(), nil)
1227		if err != nil {
1228			t.Fatal(err)
1229		}
1230		if err := SaveReport(dir, r1); err != nil {
1231			t.Fatal(err)
1232		}
1233		path := filepath.Join(dir, r1.ReportID+".json")
1234		first, _ := os.ReadFile(path)
1235		r2, err := BuildReport(sampleArtifact(), []Rule{rules[2], rules[0], rules[1]}, sampleInvariants(), nil)
1236		if err != nil {
1237			t.Fatal(err)
1238		}
1239		if r2.ReportID != r1.ReportID {
1240			t.Fatal("permutation must keep the same id")
1241		}
1242		if err := SaveReport(dir, r2); err != nil {
1243			t.Fatal(err)
1244		}
1245		second, _ := os.ReadFile(path)
1246		if string(first) != string(second) {
1247			t.Fatal("duplicate submission must not replace the first archive bytes")
1248		}
1249	}
1250	
1251	func TestSaveReportRaceCorruptFileKept(t *testing.T) {
1252		dir := t.TempDir()
1253		report, _ := BuildReport(sampleArtifact(), sampleRules(), sampleInvariants(), nil)
1254		finalPath := filepath.Join(dir, report.ReportID+".json")
1255		saveReportHook = func(string) {
1256			os.WriteFile(finalPath, []byte(`{broken`), 0o644)
1257		}
1258		defer func() { saveReportHook = nil }()
1259		err := SaveReport(dir, report)
1260		var ec errCorrupt
1261		if !errors.As(err, &ec) {
1262			t.Fatalf("expected errCorrupt, got %T: %v", err, err)
1263		}
1264		kept, _ := os.ReadFile(finalPath)
1265		if string(kept) != `{broken` {
1266			t.Fatalf("corrupt file must be kept, got %q", kept)
1267		}
1268	}
1269	
1270	func TestSaveReportConcurrentPermutations(t *testing.T) {
1271		dir := t.TempDir()
1272		rules := sampleRules()
1273		report0, _ := BuildReport(sampleArtifact(), rules, sampleInvariants(), nil)
1274		var wg sync.WaitGroup
1275		errs := make(chan error, 24)
1276		for i := 0; i < 24; i++ {
1277			wg.Add(1)
1278			go func(i int) {
1279				defer wg.Done()
1280				perm := []Rule{rules[i%3], rules[(i+1)%3], rules[(i+2)%3]}
1281				report, err := BuildReport(sampleArtifact(), perm, sampleInvariants(), nil)
1282				if err != nil {
1283					errs <- err
1284					return
1285				}
1286				errs <- SaveReport(dir, report)
1287			}(i)
1288		}
1289		wg.Wait()
1290		close(errs)
1291		for err := range errs {
1292			if err != nil {
1293				t.Fatalf("concurrent permutation save failed: %v", err)
1294			}
1295		}
1296		matches, _ := filepath.Glob(filepath.Join(dir, "*.json"))
1297		if len(matches) != 1 {
1298			t.Fatalf("expected 1 file, got %d", len(matches))
1299		}
1300		if _, err := LoadReport(dir, report0.ReportID); err != nil {
1301			t.Fatalf("final archive must be loadable: %v", err)
1302		}
1303	}
