// 目录中已有报告时，一次失败的提交必须保持原有内容原样不变。
func TestCLIAuditNullInvariantKeepsExistingReports(t *testing.T) {
	bin := auditBinary(t)
	work := t.TempDir()
	validInput := writeInput(t, work, "valid.json", validInvariantInput)
