// Package contractsentinel: strict JSON object scanning.
package contractsentinel

import (
	"bytes"
	"encoding/json"
	"fmt"
)

// rejectDuplicateJSONMembers refuses a submission whenever any single JSON
// object repeats a member name. encoding/json silently keeps the last value
// for a repeated key, so an object writing the same invariant as false then
// true would import only the pass (or null then false would smuggle a defect
// past the non-boolean rejection). A repeated key gives no single trustworthy
// conclusion and must fail the whole submission before any value is used.
//
// Comparison is on the decoded member string: a literal "inv" and the same
// name written with a Unicode escape are duplicates. Names are case
// sensitive and never trimmed. The check is structural and schema-free, so
// unknown fields receive the same treatment while identical member names in
// different objects (e.g. "id" on every rule) are normal. Text inside a
// string value that looks like JSON is never scanned.
func rejectDuplicateJSONMembers(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	// The audit submission is a single JSON object; checkObject also rejects a
	// top-level scalar/array, which json.Unmarshal would flag on its own.
	if err := checkObject(dec, ""); err != nil {
		if err == ioEOF {
			return errInvalid("invalid JSON: unexpected end of JSON input")
		}
		if se, ok := err.(*json.SyntaxError); ok {
			return errInvalid("invalid JSON: " + se.Error())
		}
		return errInvalid("invalid JSON: " + err.Error())
	}
	// Reject trailing tokens after the top-level value the same way Unmarshal does.
	if tok, err := dec.Token(); err != ioEOF {
		if err != nil {
			return errInvalid("invalid JSON: " + err.Error())
		}
		return errInvalid(fmt.Sprintf("invalid JSON: unexpected token after top-level value: %v", tok))
	}
	return nil
}

// ioEOF is compared by identity (io.EOF) without importing io everywhere.
var ioEOF = errEOF{}

type errEOF struct{}

func (errEOF) Error() string { return "EOF" }

// checkObject consumes one JSON value from dec. Object members must be unique;
// arrays and nested objects are validated recursively; scalar values are
// consumed wholesale. path locates the object for error messages.
func checkObject(dec *json.Decoder, path string) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	switch t := tok.(type) {
	default:
		// Null, bool, string or json.Number: a complete scalar value.
		return nil
	case json.Delim:
		if t != '{' && t != '[' {
			return fmt.Errorf("unexpected delimiter %q", t)
		}
		if t == '[' {
			return checkArray(dec, path)
		}
		seen := make(map[string]bool)
		for dec.More() {
			keyTok, err := dec.Token()
			if err != nil {
				return err
			}
			key, ok := keyTok.(string)
			if !ok {
				return fmt.Errorf("expected object member name, got %v", keyTok)
			}
			if seen[key] {
				return duplicateMemberError(key, path)
			}
			seen[key] = true
			child := memberPath(path, key)
			if err := checkObject(dec, child); err != nil {
				return err
			}
		}
		// Consume the closing brace.
		if _, err := dec.Token(); err != nil {
			return err
		}
		return nil
	}
}

// checkArray consumes array elements until the closing bracket. Element paths
// carry the 1-based index so a duplicate inside an array element can point at
// the exact rule or check record.
func checkArray(dec *json.Decoder, path string) error {
	i := 0
	for dec.More() {
		i++
		if err := checkObject(dec, arrayElementPath(path, i)); err != nil {
			return err
		}
	}
	if _, err := dec.Token(); err != nil {
		return err
	}
	return nil
}

// memberPath renders the path of the object a member belongs to. The path
// describes the containing object (not the member itself), which is what a
// user needs to locate the bad rule or check record.
func memberPath(parent, key string) string {
	switch parent {
	case "":
		// A direct child object of the top-level submission object.
		return key
	case "rules":
		// Rules are identified for the user once their id is known; the
		// duplicate error itself sits at "rules[i]" and is refined by the
		// caller-independent message helpers below.
		return key
	case "checks":
		return key
	}
	return parent + "." + key
}

// arrayElementPath renders the path of an object inside a JSON array.
func arrayElementPath(parent string, index int) string {
	if parent == "" {
		return fmt.Sprintf("[%d]", index)
	}
	return fmt.Sprintf("%s[%d]", parent, index)
}

// duplicateMemberError builds the user-facing "duplicate member" message.
func duplicateMemberError(key, path string) error {
	if path == "" {
		return errInvalid(fmt.Sprintf("duplicate JSON member %q in the top-level object", key))
	}
	return errInvalid(fmt.Sprintf("duplicate JSON member %q in object at %s", key, path))
}

