	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok {
		return nil, nil // null, bool, string or number: a complete scalar
	}
	switch delim {
	case '{':
		seen := make(map[string]bool)
