	switch head.key {
	case "artifact":
		if len(path) == 1 {
			return "the artifact object"
		}
		return "the artifact object (" + renderDupPath(path[1:]) + ")"
	case "invariants":
		if len(path) == 1 {
			return "the invariants object"
		}
		return "the invariants object (" + renderDupPath(path[1:]) + ")"
